  ('4.15.21.4.10', 'Conduct of 1-day planning meeting with 30 representatives from other relevant MDAs and partners on creating Community climatic Health community at 484 wards', 1163500.00::numeric, 597),
  ('4.15.21.4.11', 'Conduct of 2-days capacity building of 968 Chairman and Secretary of Created Community Climatic change committees on their roles in climate change and Health', 68266680.00::numeric, 598),
